/* ---- 新玩法插件的公用小工具（每个插件都带一份，谁先加载谁建好，后面的直接用） ---- */
if (!window.GYX) (function () {
    const X = {};
    X.bailu = () => !!window.bailuCards;                                   // 白露：不接模型，用字卡
    X.esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
