    X.set = (id, v) => { FS[id] = !!v; try { localStorage.setItem(FK, JSON.stringify(FS)); } catch (e) {} try { window.dispatchEvent(new CustomEvent('gyx:feat', { detail: { id, on: !!v } })); } catch (e) {} syncMini(); };
